#!/usr/bin/env python3
# =====================================================================
#  apply_strict_reads_all.py  —  fence STRICT_READS_ALL_20261115
#  REQUIRES apply_ledger_boot.py (LEDGER_BOOT_20261115) first.  5 of 5.
#
#  ⚠ LIVE PATH of the strategies OUTSIDE the core four, and of the older
#  slot reconciliation job.
#
#  They still called get_open_positions() / get_gtts(), which answer an empty
#  list when the broker session is not ready, and concluded "position gone /
#  GTT gone" from it — the 13/14 Nov false booking, on other strategies.
#  Every one of those call sites already treats an exception as "cannot
#  tell, do nothing this cycle"; they now call drop-in readers that raise
#  when the broker's answer cannot be read:
#     broker_truth.positions_strict / gtts_strict / infer_allowed
#   * Zerodha: an unreadable answer raises BrokerUnreadable;
#   * a broker without strict readers (Angel, Dhan): the old call, unchanged;
#   * the periodic monitors infer nothing outside the derivatives session.
#
#   jobs/scalp_v3_gtt_reconcile.py       hedge-GTT reconcile job
#   engine/ha_options/ha_trade_manager.py   GTT reconcile (positions read)
#   engine/bb_options/gtt_monitor.py        GTT monitor
#   engine/bb_options/bb_trade_state_manager.py  start-up reconcile
#   engine/tma/tma_gtt_monitor.py           GTT monitor
#   engine/broker_reconciliation.py         slot reconciliation job
#   execution/test_strict_reads_all.py      NEW — 18 checks
#
#  Run ONLY this script, outside market hours:
#     cd ~/dev/scalp-app && python3 apply_strict_reads_all.py --allow-dirty
#  Options: --repo PATH  --skip-tests  --allow-dirty  --rollback
#  Then (after all four): ./desktop/build-scalp.sh both, restart the app.
# =====================================================================
import base64, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile, zlib

FENCE = "STRICT_READS_ALL_20261115"
ITEMS = json.loads(r'''[{"path": "backend/app/engine/bb_options/bb_trade_state_manager.py", "orig": "1e5f27752221a5fd678fdfb0f9a7c75c2fa67d4b5c3731798b0967d425818b58", "new": "1804b91fa26cfd1a266597c3e0bc2504f30165033a481e89b25c0d8b584b60be", "blob": ""}, {"path": "backend/app/engine/bb_options/gtt_monitor.py", "orig": "68e0b08af491ffa35ac2dfb7ffc3cae291e9de41e7e29ceff897db96248770cb", "new": "f92672f4b55880ecc4219aa9694aeb077d5760e0fdb5afdb02a1a87dc85e5c8a", "blob": ""}, {"path": "backend/app/engine/broker_reconciliation.py", "orig": "ad5ed74db9453cb557ecba52876ad1814b4ca61d4483a95040f8802e6987ef9b", "new": "d90f0abccf1b891acc725e1c0b2f6a4031c7f053812808578a4efd1de53dd908", "blob": ""}, {"path": "backend/app/engine/ha_options/ha_trade_manager.py", "orig": "a9a7bab8e90ae4f739528ac578b923598fa91e6973e3d58245f653c96e54f1dc", "new": "e33e46611d5bd5649ad4c229357dd7ada6929f32e36b83e1f2a0f1d50fb0f0b9", "blob": ""}, {"path": "backend/app/engine/tma/test_tma_exit_paths.py", "orig": "4aa64d11210741df6a2b8ad62a9aac50450fa8c1d23e06043c3ea4561bdde09c", "new": "c2dd2124dacf0fd82f9a6aa58e84c565df3c008183c0c89a214b0146b23b84d0", "blob": ""}, {"path": "backend/app/engine/tma/tma_gtt_monitor.py", "orig": "84864f6d12bf1318c6d707d773011dc5908308f2c12c6a51a58a707c9673e313", "new": "988a48a47ce62a60fdeb560b03091b822f66fb08f12744124494bfa9fc62fd9c", "blob": ""}, {"path": "backend/app/execution/broker_truth.py", "orig": "f9bfaecfa634283e4d5d67ee891e61ae89d280b8a537e66ff294d2ac44856109", "new": "99f56bf304b4e265ea00a9187c6ed99d4a3d4b8bffb6f8942bb3c6b50be40c5b", "blob": ""}, {"path": "backend/app/execution/test_strict_reads_all.py", "orig": null, "new": "235141a89fd21d5307f9ae4054aed97cb0844005ff84f431ee728fc795c6d018", "blob": ""}, {"path": "backend/app/jobs/scalp_v3_gtt_reconcile.py", "orig": "0a908d3bd236fec1144571df101567359f3bbe11e5d7e5dd3a8d2ff9da0c9719", "new": "2a125108a39ff0a4e24a2bad2f71942bc789cf67261d73fe0fb214fc80d92a4b", "blob": ""}]''')
BUILD_COPIES = {"backend/": "desktop/src-tauri/backend/", "frontend/": "desktop/src-tauri/frontend/"}
TESTS = [         "app/execution/test_strict_reads_all.py",
         "app/execution/test_broker_truth.py",
         "app/engine/test_fleet_live.py",
         "app/engine/tma/test_tma_exit_paths.py",
         "app/engine/tma/test_tma_live_core.py",
         "app/trading/test_fleet_modes.py"
]


def sha(b):
    return hashlib.sha256(b).hexdigest()


def say(m):
    print(m, flush=True)


def die(m):
    say(f"\n✗ ABORTED — {m}\n  Nothing was changed.")
    sys.exit(1)


args = sys.argv[1:]
repo = os.path.abspath(os.path.expanduser(args[args.index("--repo") + 1])) if "--repo" in args else os.getcwd()
if not os.path.isdir(os.path.join(repo, "backend", "app")):
    alt = os.path.expanduser("~/dev/scalp-app")
    if os.path.isdir(os.path.join(alt, "backend", "app")):
        repo = alt
    else:
        die(f"{repo} is not the scalp-app repo (no backend/app) — pass --repo PATH")
say(f"repo: {repo}\nfence: {FENCE}")

# ── prerequisite: apply_ledger_boot.py
if "--rollback" not in args:
    _pf = os.path.join(repo, *['backend', 'app', 'execution', 'broker_truth.py'])
    if not os.path.exists(_pf) or 'LEDGER_BOOT_20261115' not in open(_pf, encoding="utf-8").read():
        die("run apply_ledger_boot.py first — this script builds on it")


def targets():
    """(item, absolute path, is_build_copy)"""
    out = []
    for it in ITEMS:
        out.append((it, os.path.join(repo, it["path"]), False))
        for a, b in BUILD_COPIES.items():
            if it["path"].startswith(a):
                p = os.path.join(repo, b + it["path"][len(a):])
                if os.path.isdir(os.path.dirname(p)):
                    out.append((it, p, True))
    return out


# ── rollback mode ────────────────────────────────────────────────────
if "--rollback" in args:
    n = 0
    for it, p, _ in targets():
        bak = p + ".bak-" + FENCE
        if os.path.exists(bak):
            shutil.copy2(bak, p)
            os.remove(bak)
            n += 1
        elif it["orig"] is None and os.path.exists(p):
            with open(p, "rb") as f:
                if sha(f.read()) == it["new"]:
                    os.remove(p)
                    n += 1
    say(f"rolled back {n} file(s)")
    sys.exit(0)

# ── 1. state of every target ─────────────────────────────────────────
plan, done, skipped = [], 0, []
for it, p, build in targets():
    cur = open(p, "rb").read() if os.path.exists(p) else None
    cs = sha(cur) if cur is not None else None
    rel = os.path.relpath(p, repo)
    if cs == it["new"]:
        done += 1
        continue
    if cs == it["orig"]:
        plan.append((it, p, cur, build))
        continue
    if build:
        skipped.append(rel)              # a stale build copy — the build re-syncs it
        continue
    if cur is None:
        die(f"{rel} is missing")
    die(f"{rel} differs from GitHub main and from the patched version — local edits? "
        f"(commit/stash them or pull main, then re-run)")
if not plan:
    say(f"✓ already applied ({done} file(s) carry {FENCE}) — nothing to do")
    sys.exit(0)

# ── 2. git status: an uncommitted change on a target is a stop sign ──
if "--allow-dirty" not in args:
    try:
        rels = [os.path.relpath(p, repo) for _, p, _, b in plan if not b]
        st = subprocess.run(["git", "status", "--porcelain", "--"] + rels, cwd=repo,
                            capture_output=True, text=True, timeout=30).stdout
        dirty = [l for l in st.splitlines() if l[:2].strip() and not l.startswith("??")]
        if dirty:
            die("uncommitted changes on target files:\n  " + "\n  ".join(dirty) + "\n  (re-run with --allow-dirty to override)")
    except FileNotFoundError:
        say("  (git not found — skipping the status check)")

# ── 3. decode + compile every payload before writing anything ───────
tmp = tempfile.mkdtemp(prefix="strict_reads_all_")
blobs = {}
for it in ITEMS:
    b = zlib.decompress(base64.b64decode(it["blob"]))
    if sha(b) != it["new"]:
        die(f"payload for {it['path']} is corrupt")
    blobs[it["path"]] = b
    if it["path"].endswith(".py"):
        f = os.path.join(tmp, os.path.basename(it["path"]))
        open(f, "wb").write(b)
        try:
            py_compile.compile(f, doraise=True)
        except py_compile.PyCompileError as e:
            die(f"payload {it['path']} does not compile: {e}")
say(f"payloads verified and compiled ({len(ITEMS)} files)")

# ── 4. write, all or nothing ─────────────────────────────────────────
written = []


def restore():
    for p, old in reversed(written):
        try:
            if old is None:
                os.remove(p)
            else:
                open(p, "wb").write(old)
            bak = p + ".bak-" + FENCE
            if os.path.exists(bak):
                os.remove(bak)
        except Exception as e:
            say(f"  !! could not restore {p}: {e}")


try:
    for it, p, cur, build in plan:
        if cur is not None:
            open(p + ".bak-" + FENCE, "wb").write(cur)
        t = p + ".tmp-" + FENCE
        open(t, "wb").write(blobs[it["path"]])
        os.replace(t, p)
        written.append((p, cur))
        say(f"  wrote {os.path.relpath(p, repo)}{'  (build copy)' if build else ''}")
except Exception as e:
    restore()
    die(f"write failed ({e!r}) — everything restored")
for s_ in skipped:
    say(f"  skipped stale build copy {s_} (the next build re-syncs it)")

# ── 5. tests ─────────────────────────────────────────────────────────
backend = os.path.join(repo, "backend")
py = next((c for c in (os.path.join(backend, "venv", "bin", "python"), os.path.join(backend, ".venv", "bin", "python"),
                       os.path.join(repo, "venv", "bin", "python"), os.path.join(repo, ".venv", "bin", "python"))
           if os.path.exists(c)), sys.executable)
if "--skip-tests" in args:
    say("tests skipped (--skip-tests)")
else:
    say(f"running tests with {py}")
    env = dict(os.environ, PYTHONPATH=backend, ADV_STAGE="5", SCALP_TEST_MODE="1")
    failed, envmiss = [], []
    for t in TESTS:
        if not os.path.exists(os.path.join(backend, t)):
            continue
        try:
            r = subprocess.run([py, t], cwd=backend, env=env, capture_output=True, text=True, timeout=900)
            outp = (r.stdout or "") + (r.stderr or "")
        except subprocess.TimeoutExpired:
            r, outp = None, "timeout"
        last = (outp.strip().splitlines() or [""])[-1]
        if r is not None and r.returncode == 0:
            say(f"  ✓ {t}  {last}")
        elif "ModuleNotFoundError" in outp and "No module named 'app" not in outp:
            envmiss.append(t)
            say(f"  ? {t}  could not run here: {last}")
        else:
            failed.append(t)
            say(f"  ✗ {t}\n" + "\n".join("      " + l for l in outp.strip().splitlines()[-25:]))
    if failed:
        restore()
        die("tests failed: " + ", ".join(failed) + " — every file restored")
    if envmiss:
        say("  note: some suites need the backend's Python packages; re-run them with that Python")

shutil.rmtree(tmp, ignore_errors=True)
say(f"\n✓ {FENCE} applied ({len(written)} file(s)). Next: ./desktop/build-scalp.sh both, then restart the app.")
say("  Undo: python3 apply_strict_reads_all.py --rollback")
